/// One completed unit of work.
///
/// Ownership: `data` (when non-NULL) and `message` belong to the enclosing
/// `wt_event_batch_t` and stay valid until `wt_batch_free`. `handle`/`handle2`
/// are transferred to the callee when non-NULL and must be released with the
/// matching `wt_*_free`.
final class wt_event_t extends ffi.Struct {
  /// Caller supplied correlation id (`op_id` argument of the call).
  @ffi.Uint64()
  external int op_id;

  /// `wt_op_t` of the operation that produced this event.
  @ffi.UnsignedInt()
  external int kindAsInt;

  wt_op_t get kind => wt_op_t.fromValue(kindAsInt);
  set kind(wt_op_t value) => kindAsInt = value.value;

  /// `wt_status_t` outcome.
  @ffi.Int()
  external int statusAsInt;

  wt_status_t get status => wt_status_t.fromValue(statusAsInt);
  set status(wt_status_t value) => statusAsInt = value.value;

  /// Primary produced handle, or NULL.
  external ffi.Pointer<ffi.Void> handle;

  /// Secondary produced handle (receive side of a bidirectional stream), or NULL.
  external ffi.Pointer<ffi.Void> handle2;

  /// Operation specific scalar: bytes written/read, stream id, error code, ...
  @ffi.Uint64()
  external int aux;

  /// Payload owned by the batch, or NULL.
  external ffi.Pointer<ffi.Uint8> data;

  /// Number of bytes at `data`.
  @ffi.Size()
  external int data_len;

  /// NUL-terminated diagnostic string owned by the batch, or NULL.
  external ffi.Pointer<ffi.Char> message;

  static ffi.Pointer<wt_event_t> $allocate(
    ffi.Allocator $allocator, {
    required int op_id,
    required wt_op_t kind,
    required wt_status_t status,
    required ffi.Pointer<ffi.Void> handle,
    required ffi.Pointer<ffi.Void> handle2,
    required int aux,
    required ffi.Pointer<ffi.Uint8> data,
    required int data_len,
    required ffi.Pointer<ffi.Char> message,
  }) => $allocator<wt_event_t>()
    ..ref.op_id = op_id
    ..ref.kind = kind
    ..ref.status = status
    ..ref.handle = handle
    ..ref.handle2 = handle2
    ..ref.aux = aux
    ..ref.data = data
    ..ref.data_len = data_len
    ..ref.message = message;
}

/// Event sink.
///
/// `ctx` is the pointer passed to `wt_runtime_init`. `batch` is owned by the
/// callee, which must call `wt_batch_free` when done with it. The callback is
/// invoked from a tokio worker thread, at most one thread at a time; it is
/// valid to return immediately and consume the batch later from another
/// isolate.
typedef wt_events_cb_t =
    ffi.Pointer<ffi.NativeFunction<wt_events_cb_tFunction>>;
typedef wt_events_cb_tFunction = ffi.Void Function(
  ffi.Pointer<ffi.Void> ctx,
  ffi.Pointer<wt_event_batch_t> batch,
);
typedef Dartwt_events_cb_tFunction = void Function(
  ffi.Pointer<ffi.Void> ctx,
  ffi.Pointer<wt_event_batch_t> batch,
);

